package org.eclipse.rdf4j.query.resultio.text.csv;

import static org.junit.jupiter.api.Assertions.assertEquals;

import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.nio.charset.StandardCharsets;
import java.util.List;

import org.eclipse.rdf4j.model.BNode;
import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.Value;
import org.eclipse.rdf4j.model.ValueFactory;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.BindingSet;
import org.eclipse.rdf4j.query.TupleQueryResult;
import org.eclipse.rdf4j.query.impl.IteratingTupleQueryResult;
import org.eclipse.rdf4j.query.impl.ListBindingSet;
import org.eclipse.rdf4j.query.resultio.QueryResultIO;
import org.eclipse.rdf4j.query.resultio.TupleQueryResultFormat;
import org.eclipse.rdf4j.query.resultio.helpers.QueryResultCollector;
import org.junit.jupiter.api.Test;

/**
 * Custom tests for the SPARQL CSV writer.
 */
public class SPARQLCSVCustomTest {

	private final ValueFactory vf = SimpleValueFactory.getInstance();

	@Test
	public void testIRIWithLineBreakIsQuoted() throws Exception {
		IRI iri = vf.createIRI("urn:x\nurn:forged");
		List<BindingSet> parsed = writeAndParse(iri);
		assertEquals(1, parsed.size());
		assertEquals(iri, parsed.get(0).getValue("a"));
		assertEquals(vf.createIRI("urn:b"), parsed.get(0).getValue("b"));
	}

	@Test
	public void testIRIWithCommaAndQuoteIsEscaped() throws Exception {
		IRI iri = vf.createIRI("urn:x\",urn:forged");
		List<BindingSet> parsed = writeAndParse(iri);
		assertEquals(1, parsed.size());
		assertEquals(iri, parsed.get(0).getValue("a"));
		assertEquals(vf.createIRI("urn:b"), parsed.get(0).getValue("b"));
	}

	@Test
	public void testBNodeWithSeparatorsIsQuoted() throws Exception {
		BNode bNode = vf.createBNode("x,urn:forged\nurn:row2,urn:row2b");
		List<BindingSet> parsed = writeAndParse(bNode);
		assertEquals(1, parsed.size());
		assertEquals(bNode, parsed.get(0).getValue("a"));
		assertEquals(vf.createIRI("urn:b"), parsed.get(0).getValue("b"));
	}

	private List<BindingSet> writeAndParse(Value a) throws Exception {
		List<String> bindingNames = List.of("a", "b");
		TupleQueryResult tqr = new IteratingTupleQueryResult(bindingNames,
				List.of(new ListBindingSet(bindingNames, a, vf.createIRI("urn:b"))));
		ByteArrayOutputStream output = new ByteArrayOutputStream();
		QueryResultIO.writeTuple(tqr, TupleQueryResultFormat.CSV, output);
		QueryResultCollector collector = new QueryResultCollector();
		QueryResultIO.parseTuple(new ByteArrayInputStream(output.toByteArray()), TupleQueryResultFormat.CSV,
				collector, vf);
		return collector.getBindingSets();
	}
}
